    # Locate the object and color its continuation line beyond its far edge.
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2)]
    if not cells:
        return out
    horizontal_guide = any(all(x == 2 for x in row) for row in grid)
    if horizontal_guide:
        r = max(r for r, c in cells) + 1
        if r < h:
            out[r] = [8] * w
    else:
        c = max(c for r, c in cells) + 1
        if c < w:
            for r in range(h):
                out[r][c] = 8
    return out

if __name__ == '__main__':
    print('transform defined')
